#include "cartmesh2d/fv/SstRans2D.hpp"
#include "cartmesh2d/io/MeshIO2D.hpp"
#include <fstream>
#include <iostream>
#include <iomanip>
#include <chrono>
using namespace cartmesh2d;using namespace cartmesh2d::fv;
int main(int argc,char** argv){try{
 auto topology=readCm2dTopology(argv[1]);if(!topology.valid())throw std::runtime_error(topology.error);
 auto mesh=makeFvMesh2D(topology.topology);std::ifstream in(argv[2]);std::size_t n,nf;FrozenSst2003mProblem2D p;
 in>>n>>nf>>p.nu;if(n!=mesh.cells.size()||nf!=mesh.faces.size())throw std::runtime_error("size");
 p.k.resize(n);p.omega.resize(n);p.wallDistance.resize(n);std::vector<Vector2D> velocity(n);
 for(std::size_t i=0;i<n;++i)in>>p.k[i]>>p.omega[i]>>p.wallDistance[i]>>velocity[i].x>>velocity[i].y;
 p.volumeFlux.resize(nf);p.resolvedWalls.resize(nf);p.boundaryK.resize(nf);p.boundaryOmega.resize(nf);std::vector<SstVelocityBoundary2D> bc(nf);
 for(std::size_t i=0;i<nf;++i){bool wall,value;in>>p.volumeFlux[i]>>wall>>value>>p.boundaryK[i].value>>p.boundaryOmega[i].value>>bc[i].value.x>>bc[i].value.y>>bc[i].fixedX>>bc[i].fixedY;
 p.resolvedWalls[i]=wall;p.boundaryK[i].kind=p.boundaryOmega[i].kind=value?ScalarBoundaryKind2D::Value:ScalarBoundaryKind2D::DiffusiveFlux;}
 if(!in)throw std::runtime_error("state parse");
 ScalarTransportControls2D c;c.profile=true;
 auto start=std::chrono::steady_clock::now();auto r=evaluateSst2003mTransport2D(mesh,p,velocity,bc,c);
 if(r.k.values!=p.k || r.omega.values!=p.omega)throw std::runtime_error("evaluation changed field");
 auto k=r.k.history.back(),w=r.omega.history.back();
 std::cout<<std::setprecision(17)<<"{\"kNorm\":"<<k.residualNorm<<",\"omegaNorm\":"<<w.residualNorm
 <<",\"kCell\":"<<k.maxDiagonalScaledImbalance<<",\"omegaCell\":"<<w.maxDiagonalScaledImbalance
 <<",\"kConverged\":"<<(r.k.converged?"true":"false")<<",\"omegaConverged\":"<<(r.omega.converged?"true":"false")
 <<",\"linearIterations\":"<<r.k.performance.linearIterations+r.omega.performance.linearIterations
 <<",\"unchangedFields\":true,\"seconds\":"<<std::chrono::duration<double>(std::chrono::steady_clock::now()-start).count()<<"}\n";
 return 0;

 }catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}

