#include "cartmesh2d/fv/SstRans2D.hpp"
#include "cartmesh2d/io/MeshIO2D.hpp"
#include <fstream>
#include <iostream>
#include <iomanip>
#include <chrono>
#include <algorithm>
#include <cmath>
using namespace cartmesh2d;using namespace cartmesh2d::fv;
int main(int argc,char** argv){try{
 auto topology=readCm2dTopology(argv[1]);if(!topology.valid())throw std::runtime_error(topology.error);
 auto mesh=makeFvMesh2D(topology.topology);std::ifstream in(argv[2]);std::size_t n,nf;FrozenSst2003mProblem2D p;
 in>>n>>nf>>p.nu;if(n!=mesh.cells.size()||nf!=mesh.faces.size())throw std::runtime_error("size");
 p.k.resize(n);p.omega.resize(n);p.wallDistance.resize(n);std::vector<Vector2D> velocity(n);
 for(std::size_t i=0;i<n;++i)in>>p.k[i]>>p.omega[i]>>p.wallDistance[i]>>velocity[i].x>>velocity[i].y;
 p.volumeFlux.resize(nf);p.resolvedWalls.resize(nf);p.boundaryK.resize(nf);p.boundaryOmega.resize(nf);std::vector<SstVelocityBoundary2D> bc(nf);
 for(std::size_t i=0;i<nf;++i){bool wall,value;in>>p.volumeFlux[i]>>wall>>value>>p.boundaryK[i].value>>p.boundaryOmega[i].value>>bc[i].value.x>>bc[i].value.y>>bc[i].fixedX>>bc[i].fixedY;
 p.resolvedWalls[i]=wall;p.boundaryK[i].kind=p.boundaryOmega[i].kind=value?ScalarBoundaryKind2D::Value:ScalarBoundaryKind2D::DiffusiveFlux;}
 if(!in)throw std::runtime_error("state parse");
 ScalarTransportControls2D c;
 std::vector<std::size_t> ids;double first=1e100;
 for(const auto& cell:mesh.cells)if(cell.centre.x>0)first=std::min(first,cell.centre.x);
 for(std::size_t i=0;i<n;++i)if(std::abs(mesh.cells[i].centre.x-first)<1e-12)ids.push_back(i);
 const std::size_t dim=2*ids.size();std::vector<double> scale(dim);
 for(std::size_t j=0;j<ids.size();++j){scale[j]=std::max(p.k[ids[j]],2.25e-7);scale[j+ids.size()]=std::max(p.omega[ids[j]],125.);}
 const auto measure=[&](const auto& state){return evaluateSst2003mTransport2D(mesh,state,velocity,bc,c);};
 const auto residual=[&](const auto& result){std::vector<double> q(dim);
  for(std::size_t j=0;j<dim;++j){const auto i=ids[j%ids.size()];const auto& r=j<ids.size()?result.k:result.omega;
   q[j]=r.temporalIntegrals[i]+r.sinkIntegrals[i]-r.sourceIntegrals[i];
   for(auto id:mesh.cells[i].faces){const auto& f=mesh.faces[id];q[j]+=(f.owner==i?1:-1)*(r.advectiveFlux[id]+r.diffusiveFlux[id]);}
  }return q;};
 const auto perturb=[&](auto& state,std::size_t j,double amount){(j<ids.size()?state.k:state.omega)[ids[j%ids.size()]]+=amount;};
 auto start=std::chrono::steady_clock::now();auto r=measure(p);std::ofstream out(std::string(argv[3])+".csv");
 out<<std::setprecision(17)<<"iteration,kNorm,omegaNorm,kCell,omegaCell,step\n";
 for(std::size_t it=0;it<20;++it){
  auto k=r.k.history.back(),w=r.omega.history.back();out<<it<<','<<k.residualNorm<<','<<w.residualNorm<<','<<k.maxDiagonalScaledImbalance<<','<<w.maxDiagonalScaledImbalance<<",0\n";out.flush();
  if(r.k.converged&&r.omega.converged)break;
  auto rhs=residual(r);std::vector<std::vector<double>> a(dim,std::vector<double>(dim));
  const double eps=std::stod(argv[4]);
  for(std::size_t j=0;j<dim;++j){auto plus=p,minus=p;perturb(plus,j,eps*scale[j]);perturb(minus,j,-eps*scale[j]);
   auto rp=residual(measure(plus)),rm=residual(measure(minus));for(std::size_t i=0;i<dim;++i)a[i][j]=(rp[i]-rm[i])/(2*eps);}
  for(std::size_t i=0;i<dim;++i){double row=0;for(auto v:a[i])row=std::max(row,std::abs(v));if(!(row>0))throw std::runtime_error("zero derivative row");for(auto& v:a[i])v/=row;rhs[i]=-rhs[i]/row;}
  for(std::size_t j=0;j<dim;++j){auto pivot=j;for(std::size_t i=j+1;i<dim;++i)if(std::abs(a[i][j])>std::abs(a[pivot][j]))pivot=i;
   if(std::abs(a[pivot][j])<1e-12)throw std::runtime_error("near-singular patch Jacobian");
   std::swap(a[j],a[pivot]);std::swap(rhs[j],rhs[pivot]);
   for(std::size_t i=j+1;i<dim;++i){double factor=a[i][j]/a[j][j];for(std::size_t k=j+1;k<dim;++k)a[i][k]-=factor*a[j][k];rhs[i]-=factor*rhs[j];}}
  std::vector<double> delta(dim);for(std::size_t rev=dim;rev>0;--rev){auto i=rev-1;double sum=rhs[i];for(std::size_t j=i+1;j<dim;++j)sum-=a[i][j]*delta[j];delta[i]=sum/a[i][i];}
  bool accepted=false;
  for(double lambda=1;lambda>=1./1048576;lambda*=.5){auto trial=p;bool positive=true;
   for(std::size_t j=0;j<dim;++j){perturb(trial,j,lambda*scale[j]*delta[j]);auto value=(j<ids.size()?trial.k:trial.omega)[ids[j%ids.size()]];positive=positive&&std::isfinite(value)&&(j<ids.size()?value>=0:value>0);}
   if(!positive)continue;
   auto check=measure(trial);auto ck=check.k.history.back(),cw=check.omega.history.back();
   if(ck.maxDiagonalScaledImbalance<=std::max(k.maxDiagonalScaledImbalance,1e-9)&&cw.maxDiagonalScaledImbalance<w.maxDiagonalScaledImbalance){p=std::move(trial);r=std::move(check);accepted=true;std::cerr<<it<<" step="<<lambda<<" k="<<ck.maxDiagonalScaledImbalance<<" w="<<cw.maxDiagonalScaledImbalance<<'\n';break;}}
  if(!accepted){std::cerr<<"no admissible residual-reducing patch step\n";break;}
 }
 std::cout<<std::setprecision(17)<<"{\"cellsInPatch\":"<<ids.size()<<",\"converged\":"<<(r.k.converged&&r.omega.converged?"true":"false")<<",\"kCell\":"<<r.k.history.back().maxDiagonalScaledImbalance<<",\"omegaCell\":"<<r.omega.history.back().maxDiagonalScaledImbalance<<",\"seconds\":"<<std::chrono::duration<double>(std::chrono::steady_clock::now()-start).count()<<"}\n";
 return 0;

 }catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
